import { useState } from "react";
import "./App.css";
import LengthInput from "./components/LengthInput";
import UnitSelector from "./components/UnitSelector";
import ResultDisplay from "./components/ResultDisplay";

function App() {
  const [length, setLength] = useState(10);
  const [rates, setRates] = useState({ in: 39.37, ft: 3.28, yd: 1.09 });
  const [result, setResult] = useState((10 * 39.37).toFixed(2));
  const [unit, setUnit] = useState("in");

  // 비율 하나만 바꾸고 나머지는 그대로 (객체 State는 스프레드로 복사)
  const onChangeRate = (key, value) => {
    setRates({ ...rates, [key]: value });
  };

  // 버튼을 클릭한 순간의 길이 × 비율로 계산
  const onConvert = (key) => {
    setResult((Number(length) * Number(rates[key])).toFixed(2));
    setUnit(key);
  };

  return (
    <div className="App">
      <section>
        <LengthInput length={length} onChangeLength={setLength} />
      </section>
      <section>
        <UnitSelector rates={rates} onChangeRate={onChangeRate} onConvert={onConvert} />
      </section>
      <section>
        <ResultDisplay result={result} unit={unit} />
      </section>
    </div>
  );
}

export default App;

