import { useState, useRef } from "react";
import "./App.css";
import Header from "./components/Header";
import TodoEditor from "./components/TodoEditor";
import TodoList from "./components/TodoList";

// 목(Mock) 데이터 (수정하지 마세요)
const mockTodo = [
  { id: 0, isDone: false, content: "React 공부하기", createdDate: new Date().getTime() },
  { id: 1, isDone: false, content: "빨래 널기", createdDate: new Date().getTime() },
  { id: 2, isDone: false, content: "노래 연습하기", createdDate: new Date().getTime() },
];

function App() {
  const [todo, setTodo] = useState(mockTodo);
  const idRef = useRef(3);

  const onCreate = (content) => {
    const newItem = {
      id: idRef.current,
      isDone: false,
      content,
      createdDate: new Date().getTime(),
    };
    setTodo([newItem, ...todo]);
    idRef.current += 1;
  };

  const onUpdate = (targetId) => {
    setTodo(
      todo.map((it) => (it.id === targetId ? { ...it, isDone: !it.isDone } : it))
    );
  };

  const onDelete = (targetId) => {
    setTodo(todo.filter((it) => it.id !== targetId));
  };

  return (
    <div className="App">
      <Header />
      <TodoEditor onCreate={onCreate} />
      <TodoList todo={todo} onUpdate={onUpdate} onDelete={onDelete} />
    </div>
  );
}

export default App;

