import { useState, useRef } from "react";
import "./App.css";
import Header from "./components/Header";
import StudyEditor from "./components/StudyEditor";
import StudySummary from "./components/StudySummary";
import StudyList from "./components/StudyList";

// 목(Mock) 데이터 (수정하지 마세요)
//   type: "major"(전공) 또는 "general"(교양), minutes: 공부 시간(분, 숫자), date: "YYYY-MM-DD"
const mockRecords = [
  { id: 0, type: "major", subject: "자료구조 과제", minutes: 90, date: "2026-10-20" },
  { id: 1, type: "general", subject: "영어 회화", minutes: 40, date: "2026-10-21" },
  { id: 2, type: "major", subject: "React 복습", minutes: 60, date: "2026-10-22" },
];

function App() {
  const [records, setRecords] = useState(mockRecords);
  const idRef = useRef(3);

  const onCreate = (type, subject, minutes, date) => {
    const newRecord = { id: idRef.current, type, subject, minutes, date };
    setRecords([newRecord, ...records]);
    idRef.current += 1;
  };

  const onDelete = (targetId) => {
    setRecords(records.filter((it) => it.id !== targetId));
  };

  return (
    <div className="App">
      <section>
        <Header />
      </section>
      <section>
        <StudyEditor onCreate={onCreate} />
      </section>
      <section>
        <StudySummary records={records} />
      </section>
      <section>
        <StudyList records={records} onDelete={onDelete} />
      </section>
    </div>
  );
}

export default App;

