solution.src/components/StudyList.jsx:
import { useState } from "react";
import StudyItem from "./StudyItem";
import "./StudyList.css";

const StudyList = ({ records, onDelete }) => {
  const [filter, setFilter] = useState("all");
  const [search, setSearch] = useState("");

  const filtered = records.filter(
    (it) =>
      (filter === "all" || it.type === filter) &&
      (search === "" || it.subject.toLowerCase().includes(search.toLowerCase()))
  );

  return (
    <div className="StudyList">
      <h4>공부 기록</h4>
      <div className="filter_search_wrapper">
        <select className="filter" value={filter} onChange={(e) => setFilter(e.target.value)}>
          <option value="all">전체</option>
          <option value="major">전공만</option>
          <option value="general">교양만</option>
        </select>
        <input
          className="searchbar"
          value={search}
          onChange={(e) => setSearch(e.target.value)}
          placeholder="검색어를 입력하세요"
        />
      </div>
      <div className="list_wrapper">
        {filtered.map((it) => (
          <StudyItem key={it.id} {...it} onDelete={onDelete} />
        ))}
      </div>
    </div>
  );
};

export default StudyList;

