import "./StudySummary.css";

const StudySummary = ({ records }) => {
  let major = 0;
  let general = 0;
  records.forEach((it) => {
    if (it.type === "major") {
      major += it.minutes;
    } else {
      general += it.minutes;
    }
  });
  const total = major + general;

  return (
    <div className="StudySummary">
      <div className="summary_item major">
        <div className="label">전공</div>
        <div className="value">{major}분</div>
      </div>
      <div className="summary_item general">
        <div className="label">교양</div>
        <div className="value">{general}분</div>
      </div>
      <div className="summary_item total">
        <div className="label">합계</div>
        <div className="value">{total}분</div>
      </div>
    </div>
  );
};

export default StudySummary;

