import { useState, useRef } from "react";
import "./App.css";
import OrderColumn from "./components/OrderColumn";

// 주문 상태 순서 (왼쪽 → 오른쪽). 수정하지 마세요.
//   "received": 주문 접수 / "making": 제조 중 / "done": 픽업 완료
const STATUSES = ["received", "making", "done"];

// 목(Mock) 데이터 (수정하지 마세요)
const mockOrders = [
  { id: 0, menu: "아이스 아메리카노", status: "received" },
  { id: 1, menu: "카페라떼", status: "received" },
  { id: 2, menu: "바닐라라떼", status: "making" },
  { id: 3, menu: "녹차라떼", status: "done" },
];

function App() {
  const [orders, setOrders] = useState(mockOrders);
  const idRef = useRef(4);

  const onCreate = (menu, status) => {
    setOrders([...orders, { id: idRef.current, menu, status }]);
    idRef.current += 1;
  };

  const onDelete = (targetId) => {
    setOrders(orders.filter((order) => order.id !== targetId));
  };

  const onMove = (targetId, direction) => {
    setOrders(
      orders.map((order) => {
        if (order.id !== targetId) return order;
        const next = STATUSES.indexOf(order.status) + direction;
        if (next < 0 || next >= STATUSES.length) return order;
        return { ...order, status: STATUSES[next] };
      })
    );
  };

  return (
    <div className="App">
      <div className="header">
        <h2>☕ 카페 주문 현황판</h2>
      </div>
      <div className="board">
        <OrderColumn
          title="주문 접수"
          status="received"
          orders={orders.filter((order) => order.status === "received")}
          onCreate={onCreate}
          onDelete={onDelete}
          onMove={onMove}
        />
        <OrderColumn
          title="제조 중"
          status="making"
          orders={orders.filter((order) => order.status === "making")}
          onCreate={onCreate}
          onDelete={onDelete}
          onMove={onMove}
        />
        <OrderColumn
          title="픽업 완료"
          status="done"
          orders={orders.filter((order) => order.status === "done")}
          onCreate={onCreate}
          onDelete={onDelete}
          onMove={onMove}
        />
      </div>
    </div>
  );
}

export default App;

