solution.src/components/OrderColumn.jsx:
import { useState } from "react";
import OrderCard from "./OrderCard";
import "./OrderColumn.css";

const OrderColumn = ({ title, status, orders, onCreate, onDelete, onMove }) => {
  const [menu, setMenu] = useState("");

  const onSubmit = () => {
    if (menu === "") {
      return;
    }
    onCreate(menu, status);
    setMenu("");
  };

  return (
    <div className="OrderColumn">
      <div className="column-header">
        <h3>{title}</h3>
        <span className="count">{orders.length}</span>
      </div>
      <div className="order-editor">
        <input value={menu} onChange={(e) => setMenu(e.target.value)} placeholder="메뉴 이름" />
        <button onClick={onSubmit}>추가</button>
      </div>
      <div className="cards">
        {orders.map((order) => (
          <OrderCard key={order.id} order={order} onDelete={onDelete} onMove={onMove} />
        ))}
      </div>
    </div>
  );
};

export default OrderColumn;

