import { useState, useRef, useEffect } from "react";
import "./MemoEditor.css";

const MAX_LENGTH = 30;

const MemoEditor = ({ onCreate }) => {
  const [content, setContent] = useState("");
  const inputRef = useRef();

  // 빈 의존성 배열 → 마운트될 때 한 번만 실행
  useEffect(() => {
    inputRef.current.focus();
  }, []);

  const onChangeContent = (e) => {
    setContent(e.target.value);
  };

  const onSubmit = () => {
    if (content.length < 5) {
      inputRef.current.focus();
      return;
    }
    onCreate(content);
    setContent("");
  };

  return (
    <div className="MemoEditor">
      <div className="editor_wrapper">
        <input
          ref={inputRef}
          className="memo_input"
          value={content}
          onChange={onChangeContent}
          maxLength={MAX_LENGTH}
          placeholder="메모를 입력하세요 (5글자 이상)"
        />
        <button onClick={onSubmit}>등록</button>
      </div>
      <div className="char_count">
        {content.length} / {MAX_LENGTH}
      </div>
    </div>
  );
};

export default MemoEditor;

solution.src/components/MemoList.jsx:
import { useState } from "react";
import "./MemoList.css";

const MemoList = ({ memos }) => {
  const [search, setSearch] = useState("");

  const onChangeSearch = (e) => {
    setSearch(e.target.value);
  };

  const filteredMemos =
    search === "" ? memos : memos.filter((memo) => memo.content.includes(search));

  return (
    <div className="MemoList">
      <input
        className="searchbar"
        value={search}
        onChange={onChangeSearch}
        placeholder="메모 검색"
      />
      <ul className="list_wrapper">
        {filteredMemos.map((memo) => (
          <li key={memo.id} className="MemoItem">
            {memo.content}
          </li>
        ))}
      </ul>
    </div>
  );
};

export default MemoList;

